import UIKit
import SwiftUI

enum AppAssets {
    static let zhLogoBase64 = ""
    static let husseinBase64 = ""
    static let abboudBase64 = ""

    static var zhLogo: UIImage? {
        guard let data = Data(base64Encoded: zhLogoBase64) else { return nil }
        return UIImage(data: data)
    }

    static var husseinPhoto: UIImage? {
        guard let data = Data(base64Encoded: husseinBase64) else { return nil }
        return UIImage(data: data)
    }

    static var abboudPhoto: UIImage? {
        guard let data = Data(base64Encoded: abboudBase64) else { return nil }
        return UIImage(data: data)
    }
}
